class FeatureFlags:
    def __init__(self):
        self._flags = {}

    def set(self, name, enabled):
        self._flags[name] = enabled

    def get(self, name):
        return self._flags.get(name, False)

    def search(self):
        return list(self._flags.keys())

    def export(self):
        return self._flags

