class Permissions:
    def allowed(self, role, action):
        if role == "viewer":
            return action == "read"
        elif role == "editor":
            return action in ("read", "write")
        else:
            return False

class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": {"read": True, "write": False},
            "editor": {"read": True, "write": True},
        }

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        return self.roles[role].get(action, False)

class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": ["read"],
            "editor": ["read", "write"],
        }

    def allowed(self, role, action):
        return action in self.roles.get(role, [])

